\sum_i\nabla_{e_i}\Ric(e_i,X)\:=\:\frac12\langle\nabla R,X\rangle,
\end{equation}
and
\begin{equation}
\sum_i\Ric_t(e_i,e_i)\:=\:\triangle R.
\end{equation}
